-- Security/privacy completion migration applied to Supabase Open Claude on 2026-10-07.
create table if not exists public.auth_attempts (id uuid primary key default gen_random_uuid(),email_hash text not null,ip_hash text not null,success boolean not null default false,reason text,created_at timestamptz not null default now());
create index if not exists auth_attempts_lookup_idx on public.auth_attempts(email_hash,ip_hash,created_at desc);
create table if not exists public.account_suspensions (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,reason text not null,source text not null default 'manual',starts_at timestamptz not null default now(),ends_at timestamptz,active boolean not null default true,metadata jsonb not null default '{}',created_at timestamptz not null default now());
alter table public.auth_attempts enable row level security; revoke all on public.auth_attempts from anon,authenticated;
alter table public.account_suspensions enable row level security;
drop policy if exists account_suspensions_owner_select on public.account_suspensions;
create policy account_suspensions_owner_select on public.account_suspensions for select to authenticated using((select auth.uid())=user_id);
revoke insert,update,delete on public.account_suspensions from anon,authenticated; grant select on public.account_suspensions to authenticated;
create table if not exists public.privacy_consents (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,version text not null,necessary boolean not null default true,analytics boolean not null default false,functional boolean not null default false,marketing boolean not null default false,source text not null default 'settings',accepted_at timestamptz not null default now(),unique(user_id,version));
alter table public.privacy_consents enable row level security;
drop policy if exists privacy_consents_owner_all on public.privacy_consents;
create policy privacy_consents_owner_all on public.privacy_consents for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
revoke all on public.privacy_consents from anon; grant select,insert,update on public.privacy_consents to authenticated;
create table if not exists public.data_subject_requests (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,request_type text not null check(request_type in ('access','correction','portability','deletion','restriction','subprocessor')),status text not null default 'received' check(status in ('received','processing','completed','rejected')),details jsonb not null default '{}',created_at timestamptz not null default now(),completed_at timestamptz);
alter table public.data_subject_requests enable row level security;
create policy data_requests_owner_select on public.data_subject_requests for select to authenticated using((select auth.uid())=user_id);
create policy data_requests_owner_insert on public.data_subject_requests for insert to authenticated with check((select auth.uid())=user_id);
revoke update,delete on public.data_subject_requests from anon,authenticated; grant select,insert on public.data_subject_requests to authenticated;
create table if not exists public.security_reports (id uuid primary key default gen_random_uuid(),reporter_id uuid references auth.users(id) on delete set null,category text not null,description text not null,status text not null default 'received' check(status in ('received','reviewing','resolved','dismissed')),review_notes text,created_at timestamptz not null default now(),resolved_at timestamptz);
alter table public.security_reports enable row level security;
create policy security_reports_owner_select on public.security_reports for select to authenticated using((select auth.uid())=reporter_id);
create policy security_reports_owner_insert on public.security_reports for insert to authenticated with check((select auth.uid())=reporter_id);
revoke update,delete on public.security_reports from anon,authenticated; grant select,insert on public.security_reports to authenticated;
create table if not exists public.cookie_inventory (id uuid primary key default gen_random_uuid(),name text not null unique,category text not null,purpose text not null,provider text,duration text,http_only boolean not null default true,secure boolean not null default true,same_site text,active boolean not null default true,updated_at timestamptz not null default now());
alter table public.cookie_inventory enable row level security;
create policy cookie_inventory_public_select on public.cookie_inventory for select to authenticated using(true);
revoke insert,update,delete on public.cookie_inventory from anon,authenticated; grant select on public.cookie_inventory to authenticated;
insert into public.cookie_inventory(name,category,purpose,provider,duration,http_only,secure,same_site) values ('sb-access-token','necessary','Sessão de autenticação','Supabase','sessão',true,true,'lax'),('sb-refresh-token','necessary','Renovação de sessão','Supabase','sessão persistente',true,true,'lax') on conflict(name) do update set updated_at=now();
create table if not exists public.security_alerts (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,type text not null,severity text not null default 'info' check(severity in ('info','warning','critical')),title text not null,message text not null,acknowledged_at timestamptz,created_at timestamptz not null default now());
alter table public.security_alerts enable row level security;
create policy security_alerts_owner_all on public.security_alerts for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
revoke all on public.security_alerts from anon; grant select,update on public.security_alerts to authenticated;
create table if not exists public.subprocessor_deletion_jobs (id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,processor text not null,reference text,status text not null default 'queued' check(status in ('queued','sent','confirmed','failed')),requested_at timestamptz not null default now(),completed_at timestamptz,metadata jsonb not null default '{}');
alter table public.subprocessor_deletion_jobs enable row level security; revoke all on public.subprocessor_deletion_jobs from anon,authenticated;
create or replace function public.cleanup_privacy_security_retention() returns jsonb language plpgsql security invoker set search_path=public as $$ declare a bigint:=0;s bigint:=0;h bigint:=0;begin delete from public.auth_attempts where created_at<now()-interval '90 days';get diagnostics h=row_count;delete from public.security_events where created_at<now()-interval '180 days';get diagnostics s=row_count;delete from public.audit_logs where created_at<now()-interval '180 days';get diagnostics a=row_count;update public.account_suspensions set active=false where active and ends_at is not null and ends_at<now();return jsonb_build_object('auth_attempts',h,'security_events',s,'audit_logs',a);end;$$;
revoke all on function public.cleanup_privacy_security_retention() from public;